function topK(items, k) {
  // Validate k
  if (!Number.isInteger(k) || k < 0) {
    throw new RangeError('k must be a non-negative integer');
  }

  // Validate items
  if (!Array.isArray(items) || !items.every(item => typeof item === 'string')) {
    throw new TypeError('items must be an array of strings');
  }

  // Count frequencies
  const counts = {};
  for (const item of items) {
    counts[item] = (counts[item] || 0) + 1;
  }

  // Convert to array of [string, count] pairs and sort
  const sorted = Object.entries(counts)
    .sort((a, b) => {
      // First by count (descending)
      if (b[1] !== a[1]) {
        return b[1] - a[1];
      }
      // Then alphabetically (ascending, UTF-16 order via <)
      return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0;
    })
    .slice(0, k)
    .map(([str]) => str);

  return sorted;
}

module.exports = { topK };
"}
